14	class TimelineMediaPreviewController: QLPreviewController {
15	    private let context: TimelineMediaPreviewViewModel.Context
16	    
17	    private let headerHostingController: UIHostingController<HeaderView>
18	    private let detailsButtonHostingController: UIHostingController<DetailsButton>
19	    private let captionHostingController: UIHostingController<CaptionView>
20	    private let downloadIndicatorHostingController: UIHostingController<DownloadIndicatorView>
21	    private var detailsHostingController: UIHostingController<TimelineMediaPreviewDetailsView>?
22	    
23	    private var barButtonTimer: Timer?
24	    
25	    private var cancellables: Set<AnyCancellable> = []
26	    
27	    private var navigationBar: UINavigationBar? {
28	        view.subviews.first?.subviews.first { $0 is UINavigationBar } as? UINavigationBar
29	    }
30	
31	    private var bottomBarItemsContainer: UIView? {
32	        if #available(iOS 26, *) {
33	            view.subviews.first?.subviews.last?.subviews.first
34	        } else {
35	            view.subviews.first?.subviews.last { $0 is UIToolbar }
36	        }
37	    }
38	
39	    private var pageScrollView: UIScrollView? {
40	        view.firstScrollView()
41	    }
42	
43	    private var captionView: UIView {
44	        captionHostingController.view
45	    }
46	    
47	    override var overrideUserInterfaceStyle: UIUserInterfaceStyle {
48	        get { .dark }
49	        set { }
50	    }
51	    
52	    init(context: TimelineMediaPreviewViewModel.Context) {
53	        self.context = context
54	        
55	        headerHostingController = UIHostingController(rootView: HeaderView(context: context))
56	        headerHostingController.view.backgroundColor = .clear
57	        headerHostingController.sizingOptions = .intrinsicContentSize
58	        detailsButtonHostingController = UIHostingController(rootView: DetailsButton(context: context))
59	        detailsButtonHostingController.view.backgroundColor = .clear
60	        detailsButtonHostingController.sizingOptions = .intrinsicContentSize
61	        captionHostingController = UIHostingController(rootView: CaptionView(context: context))
62	        captionHostingController.view.backgroundColor = .clear
63	        captionHostingController.sizingOptions = .intrinsicContentSize
64	        downloadIndicatorHostingController = UIHostingController(rootView: DownloadIndicatorView(context: context))
65	        downloadIndicatorHostingController.view.backgroundColor = .clear
66	        downloadIndicatorHostingController.sizingOptions = .intrinsicContentSize
67	        
68	        super.init(nibName: nil, bundle: nil)
69	        
70	        view.addSubview(captionView)
71	        // Constraints added later as the toolbar isn't available yet.
72	        
73	        view.addSubview(downloadIndicatorHostingController.view)
74	        downloadIndicatorHostingController.view.translatesAutoresizingMaskIntoConstraints = false
75	        NSLayoutConstraint.activate([
76	            downloadIndicatorHostingController.view.centerXAnchor.constraint(equalTo: view.centerXAnchor),
77	            downloadIndicatorHostingController.view.centerYAnchor.constraint(equalTo: view.centerYAnchor)
78	        ])
79	        
80	        // Observation of currentPreviewItem doesn't work, so use the index instead.
81	        publisher(for: \.currentPreviewItemIndex)
82	            .sink { [weak self] _ in
83	                // This isn't removing duplicates which may try to download and/or write to disk concurrently????
84	                self?.loadCurrentItem()
85	            }
86	            .store(in: &cancellables)
87	        
88	        context.viewState.dataSource.previewItemsPaginationPublisher
89	            .sink { [weak self] in
90	                self?.handleUpdatedItems()
91	            }
92	            .store(in: &cancellables)
93	        
94	        context.viewState.previewControllerDriver
95	            .sink { [weak self] action in
96	                switch action {
97	                case .itemLoaded(let itemID):
98	                    self?.handleFileLoaded(itemID: itemID)
99	                case .showItemDetails(let mediaItem):
100	                    self?.presentMediaDetails(for: mediaItem)
101	                case .exportFile(let file):
102	                    self?.exportFile(file)
103	                case .authorizationRequired(let appMediator):
104	                    self?.presentAuthorizationRequiredAlert(appMediator: appMediator)
105	                case .dismissDetailsSheet:
106	                    self?.dismiss(animated: true)
107	                }
108	            }
109	            .store(in: &cancellables)
110	        
111	        dataSource = context.viewState.dataSource
112	        currentPreviewItemIndex = context.viewState.dataSource.initialItemIndex
113	    }
114	    
115	    @available(*, unavailable) required init?(coder: NSCoder) {
116	        fatalError("init(coder:) has not been implemented")
117	    }
118	    
119	    // MARK: Layout
120	    
121	    override func viewWillLayoutSubviews() {
122	        super.viewWillLayoutSubviews()
123	        
124	        if let bottomBarItemsContainer {
125	            // Using the toolbar's visibility doesn't work so check its frame.
126	            captionView.isHidden = if #available(iOS 26, *) {
127	                navigationBar?.topItem?.leftBarButtonItem?.frame(in: view) == nil
128	            } else {
129	                bottomBarItemsContainer.frame.minY >= view.frame.maxY
130	            }
131	            
132	            if captionView.constraints.isEmpty {
133	                captionHostingController.view.translatesAutoresizingMaskIntoConstraints = false
134	                
135	                let bottomConstraint = if #available(iOS 26, *) {
136	                    captionView.bottomAnchor.constraint(equalTo: bottomBarItemsContainer.safeAreaLayoutGuide.bottomAnchor, constant: -50)
137	                } else {
138	                    captionView.bottomAnchor.constraint(equalTo: bottomBarItemsContainer.topAnchor)
139	                }
140	                
141	                NSLayoutConstraint.activate([
142	                    bottomConstraint,
143	                    captionView.leadingAnchor.constraint(equalTo: bottomBarItemsContainer.leadingAnchor),
144	                    captionView.trailingAnchor.constraint(equalTo: bottomBarItemsContainer.trailingAnchor)
145	                ])
146	            }
147	        }
148	        
149	        navigationBar?.topItem?.titleView = headerHostingController.view
150	        
151	        updateBarButtons()
152	        
153	        // Ridiculous hack to undo the controller's attempt to replace our info button with the list button.
154	        if barButtonTimer == nil {
155	            barButtonTimer = Timer.scheduledTimer(withTimeInterval: 0.1, repeats: true) { [weak self] _ in
156	                self?.updateBarButtons()
157	            }
158	        }
159	    }
160	    
161	    override func viewWillDisappear(_ animated: Bool) {
162	        barButtonTimer?.invalidate()
163	        barButtonTimer = nil
164	    }
165	    
166	    private func updateBarButtons() {
167	        guard let topItem = navigationBar?.topItem else { return }
168	        
169	        if topItem.leftBarButtonItem?.customView == nil {
170	            let button = UIBarButtonItem(customView: detailsButtonHostingController.view)
171	            navigationBar?.topItem?.leftBarButtonItem = button
172	        }
173	    }
174	    
175	    // MARK: Item loading
176	    
177	    private func loadCurrentItem() {
178	        headerHostingController.view.sizeToFit() // Resizing isn't automatic in the toolbar 😒
179	        
180	        if let previewItem = currentPreviewItem as? TimelineMediaPreviewItem.Media {
181	            context.send(viewAction: .updateCurrentItem(.media(previewItem)))
182	        } else if let loadingItem = currentPreviewItem as? TimelineMediaPreviewItem.Loading {
183	            switch loadingItem.state {
184	            case .paginating:
185	                context.send(viewAction: .updateCurrentItem(.loading(loadingItem)))
186	            case .timelineStart:
187	                Task { await returnToIndex(context.viewState.dataSource.firstPreviewItemIndex) }
188	            case .timelineEnd:
189	                Task { await returnToIndex(context.viewState.dataSource.lastPreviewItemIndex) }
190	            }
191	        } else {
192	            MXLog.error("Unexpected preview item type: \(type(of: currentPreviewItem))")
193	        }
194	    }
195	    
196	    private func returnToIndex(_ index: Int) async {
197	        // Sleep to fix a bug where the update didn't take effect when the swipe velocity was slow.
198	        try? await Task.sleep(for: .seconds(0.1))
199	        
200	        currentPreviewItemIndex = index
201	        context.send(viewAction: .timelineEndReached)
202	    }
203	    
204	    private func handleUpdatedItems() {
205	        if currentPreviewItem is TimelineMediaPreviewItem.Loading {
206	            let dataSource = context.viewState.dataSource
207	            if dataSource.previewController(self, previewItemAt: currentPreviewItemIndex) is TimelineMediaPreviewItem.Media {
208	                refreshCurrentPreviewItem() // This will trigger loadCurrentItem automatically.
209	            }
210	        }
211	    }
212	    
213	    private func handleFileLoaded(itemID: TimelineItemIdentifier.EventOrTransactionID) {
214	        guard (currentPreviewItem as? TimelineMediaPreviewItem.Media)?.id == itemID else { return }
215	        
216	        // There's a bug where refreshCurrentPreviewItem completely breaks the QLPreviewController
217	        // if it's called whilst swiping between items. So don't let that happen.
218	        if let scrollView = pageScrollView, scrollView.isDragging || scrollView.isDecelerating {
219	            return
220	        }
221	        
222	        refreshCurrentPreviewItem()
223	    }
224	    
225	    // MARK: - Actions
226	    
227	    private func presentMediaDetails(for mediaItem: TimelineMediaPreviewItem.Media) {
228	        let safeArea = view.safeAreaInsets.bottom
229	        let sheetHeightBinding = Binding { safeArea } set: { [weak self] newValue, _ in
230	            self?.detailsHostingController?.sheetPresentationController?.detents = [.height(newValue + safeArea)]
231	        }
232	        
233	        let hostingController = UIHostingController(rootView: TimelineMediaPreviewDetailsView(item: mediaItem,
234	                                                                                              context: context,
235	                                                                                              sheetHeight: sheetHeightBinding))
236	        hostingController.view.backgroundColor = .compound.bgCanvasDefault
237	        hostingController.overrideUserInterfaceStyle = .dark
238	        hostingController.sheetPresentationController?.detents = [.height(safeArea)]
239	        hostingController.sheetPresentationController?.prefersGrabberVisible = true
240	        
241	        present(hostingController, animated: true)
242	        
243	        detailsHostingController = hostingController
244	    }
245	    
246	    private func exportFile(_ file: TimelineMediaPreviewFileExportPicker.File) {
247	        let hostingController = UIHostingController(rootView: TimelineMediaPreviewFileExportPicker(file: file))
248	        present(hostingController, animated: true)
249	    }
250	    
251	    private func presentAuthorizationRequiredAlert(appMediator: AppMediatorProtocol) {
252	        let alertController = UIAlertController(title: L10n.dialogPermissionPhotoLibraryTitleIos(InfoPlistReader.main.bundleDisplayName),
253	                                                message: nil,
254	                                                preferredStyle: .alert)
255	        alertController.addAction(.init(title: L10n.commonSettings, style: .default) { _ in appMediator.openAppSettings() })
256	        alertController.addAction(.init(title: L10n.actionCancel, style: .cancel))
257	        
258	        present(alertController, animated: true)
259	    }
260	}
