338	private struct DownloadIndicatorView: View {
339	    @ObservedObject var context: TimelineMediaPreviewViewModel.Context
340	    private var currentItem: TimelineMediaPreviewItem {
341	        context.viewState.currentItem
342	    }
343	    
344	    private var shouldShowDownloadIndicator: Bool {
345	        switch currentItem {
346	        case .media(let mediaItem): mediaItem.fileHandle == nil
347	        case .loading(.paginatingBackwards), .loading(.paginatingForwards): true
348	        case .loading: false
349	        }
350	    }
351	    
352	    var body: some View {
353	        if case let .media(mediaItem) = currentItem, mediaItem.downloadError != nil {
354	            VStack(spacing: 24) {
355	                CompoundIcon(\.errorSolid, size: .custom(48), relativeTo: .compound.headingLG)
356	                    .foregroundStyle(.compound.iconCriticalPrimary)
357	                    .padding(.vertical, 24.5)
358	                    .padding(.horizontal, 28.5)
359	                
360	                VStack(spacing: 2) {
361	                    Text(L10n.commonDownloadFailed)
362	                        .font(.compound.headingMDBold)
363	                        .foregroundStyle(.compound.textPrimary)
364	                        .multilineTextAlignment(.center)
365	                    Text(L10n.screenMediaBrowserDownloadErrorMessage)
366	                        .font(.compound.bodyMD)
367	                        .foregroundStyle(.compound.textPrimary)
368	                        .multilineTextAlignment(.center)
369	                }
370	            }
371	            .padding(.horizontal, 24)
372	            .padding(.vertical, 40)
373	            .background(.compound.bgSubtlePrimary, in: RoundedRectangle(cornerRadius: 14))
374	        } else if shouldShowDownloadIndicator {
375	            ProgressView()
376	                .controlSize(.large)
377	                .tint(.compound.iconPrimary)
378	        }
379	    }
380	}
