54	struct TimelineMediaPreviewViewState: BindableState {
55	    /// The data source for all of the preview-able items.
56	    var dataSource: TimelineMediaPreviewDataSource
57	    
58	    /// The media item that is currently being previewed.
59	    var currentItem: TimelineMediaPreviewItem {
60	        dataSource.currentItem
61	    }
62	
63	    /// All of the available actions for the current item.
64	    var currentItemActions: TimelineItemMenuActions?
65	    
66	    /// A publisher that the view model uses to signal actions to the QLPreviewController.
67	    let previewControllerDriver = PassthroughSubject<TimelineMediaPreviewDriverAction, Never>()
68	    
69	    var bindings = TimelineMediaPreviewViewStateBindings()
70	}
71	
72	struct TimelineMediaPreviewViewStateBindings {
73	    /// A binding that will present a confirmation to redact the specified item.
74	    var redactConfirmationItem: TimelineMediaPreviewItem.Media?
75	}
