13	
14	struct RoomScreen: View {
15	    @ObservedObject private var context: RoomScreenViewModelType.Context
16	    @ObservedObject private var timelineContext: TimelineViewModelType.Context
17	    let composerToolbar: ComposerToolbar
18	    @Environment(\.accessibilityVoiceOverEnabled) private var isVoiceOverEnabled
19	
20	    init(context: RoomScreenViewModelType.Context,
21	         timelineContext: TimelineViewModelType.Context,
22	         composerToolbar: ComposerToolbar) {
23	        self.context = context
24	        self.timelineContext = timelineContext
25	        self.composerToolbar = composerToolbar
26	    }
27	
28	    var body: some View {
29	        TimelineView(timelineContext: timelineContext)
30	            .overlay(alignment: .bottomTrailing) {
31	                TimelineScrollToBottomButton(isVisible: isAtBottomAndLive) {
32	                    timelineContext.send(viewAction: .scrollToBottom)
33	                }
34	                .accessibilityIdentifier(A11yIdentifiers.roomScreen.scrollToBottom)
35	            }
36	            .background(Color.compound.bgCanvasDefault.ignoresSafeArea())
37	            .topBanners([
38	                TopBannerLayer(verticalBanners: [
39	                    TopBannerItem(pinnedItemsBanner, isVisible: context.viewState.shouldShowPinnedEventsBanner && !isVoiceOverEnabled),
40	                    TopBannerItem(liveLocationBanner, isVisible: context.viewState.isSharingLiveLocation && !isVoiceOverEnabled)
41	                ]),
42	                // This can overlay on top of the stacked banners
43	                TopBannerLayer(knockRequestsBanner, isVisible: context.viewState.shouldSeeKnockRequests)
44	            ], footer: dateBadge)
45	            .safeAreaInset(edge: .top) {
46	                // When VoiceOver is enabled, the table view isn't reversed and the scroll gestures
47	                // don't trigger meaning the banner never hides itself and so the .overlay layout
48	                // above permanently obscures the top of the timeline. So whenever VoiceOver is
49	                // enabled we use a safe area inset to vertically stack it above the timeline.
50	                if context.viewState.shouldShowPinnedEventsBanner || context.viewState.isSharingLiveLocation, isVoiceOverEnabled {
51	                    VStack(spacing: 0) {
52	                        if context.viewState.shouldShowPinnedEventsBanner {
53	                            pinnedItemsBanner
54	                        }
55	                        if context.viewState.isSharingLiveLocation {
56	                            liveLocationBanner
57	                        }
58	                    }
59	                }
60	            }
61	            .safeAreaInset(edge: .bottom, spacing: 0) {
62	                VStack(spacing: 0) {
63	                    RoomScreenFooterView(details: context.viewState.footerDetails,
64	                                         mediaProvider: context.mediaProvider) { action in
65	                        context.send(viewAction: .footerViewAction(action))
66	                    }
67	                    
68	                    composer
69	                        .padding(.top, 8)
70	                        .background(Color.compound.bgCanvasDefault.ignoresSafeArea())
71	                        .environmentObject(timelineContext)
72	                        .environment(\.timelineContext, timelineContext)
73	                        // Make sure the reply header honours the hideTimelineMedia setting too.
74	                        .environment(\.shouldAutomaticallyLoadImages, !timelineContext.viewState.hideTimelineMedia)
75	                }
76	            }
77	            .toolbarRole(RoomHeaderView.toolbarRole)
78	            .navigationTitle(L10n.screenRoomTitle) // Hidden but used for back button text.
79	            .navigationBarTitleDisplayMode(.inline)
80	            .toolbar { toolbar }
81	            .toolbarBackground(.visible, for: .navigationBar) // Fix the toolbar's background.
82	            .overlay { loadingIndicator }
83	            .alert(item: $context.alertInfo)
84	            .timelineMediaPreview(viewModel: $context.mediaPreviewViewModel)
85	            .track(screen: .Room)
86	            .sentryTrace("\(Self.self)")
87	    }
88	    
89	    private var liveLocationBanner: some View {
90	        LiveLocationSharingBannerView {
91	            context.send(viewAction: .tappedStopLiveLocation)
92	        }
93	    }
94	    
95	    private var pinnedItemsBanner: some View {
96	        PinnedItemsBannerView(state: context.viewState.pinnedEventsBannerState,
97	                              onMainButtonTap: { context.send(viewAction: .tappedPinnedEventsBanner) },
98	                              onViewAllButtonTap: { context.send(viewAction: .viewAllPins) })
99	    }
100	    
101	    private var knockRequestsBanner: some View {
102	        KnockRequestsBannerView(requests: context.viewState.displayedKnockRequests,
103	                                onDismiss: dismissKnockRequestsBanner,
104	                                onAccept: context.viewState.canAcceptKnocks ? acceptKnockRequest : nil,
105	                                onViewAll: onViewAllKnockRequests,
106	                                mediaProvider: context.mediaProvider)
107	            .padding(.top, 16)
108	    }
109	    
110	    @ViewBuilder
111	    private var dateBadge: some View {
112	        if !isVoiceOverEnabled {
113	            FloatingDateBadge(dateText: timelineContext.floatingDate?.formattedDateSeparator()) {
114	                timelineContext.send(viewAction: .scrollToFirstItemForCurrentDate)
115	            }
116	        }
117	    }
118	    
119	    private func dismissKnockRequestsBanner() {
120	        context.send(viewAction: .dismissKnockRequests)
121	    }
122	    
123	    private func acceptKnockRequest(eventID: String) {
124	        context.send(viewAction: .acceptKnock(eventID: eventID))
125	    }
126	    
127	    private func onViewAllKnockRequests() {
128	        context.send(viewAction: .viewKnockRequests)
129	    }
130	    
131	    private var isAtBottomAndLive: Bool {
132	        timelineContext.isScrolledToBottom && timelineContext.viewState.timelineState.isLive
133	    }
134	    
135	    @ViewBuilder
136	    private var composer: some View {
137	        if context.viewState.hasSuccessor {
138	            tombstonedDialogue
139	        } else if context.viewState.canSendMessage, !ProcessInfo.isRunningAccessibilityTests {
140	            // We are not sure why but when wrapped in the room screen the composer toolbar breaks the accessibility tests
141	            composerToolbar
142	        } else {
143	            ComposerDisabledView()
144	        }
145	    }
